changeSet.sql:
ALTER procedure [metrics].[LoadFromStaging] as begin set nocount on;
DECLARE @TranName VARCHAR(20); SELECT @TranName = 'UpdateScores'; begin transaction @TranName;
begin try -- Only get the unique set of score items with changes over time based on effective date. with RN as ( select ROW_NUMBER() OVER (PARTITION BY AssetUid, MetricAssetUid ORDER BY AssetUid, MetricAssetUid, EffectiveDate) as RowNumber, MAX(UpdatedOn) OVER (PARTITION BY AssetUid, MetricAssetUid) as MaxUpdatedOn, * from metrics.ScoreItem )
delete T from metrics.ScoreItem T left join ( select C.AssetUid, C.MetricAssetUid, C.EffectiveDate, C.MaxUpdatedOn as UpdatedOn, C.Value, C.AdjustedWeight from RN C left join RN N on N.AssetUid = C.AssetUid and N.MetricAssetUid = C.MetricAssetUid and N.RowNumber = C.RowNumber-1 and N.AdjustedWeight <> C.AdjustedWeight where N.RowNumber is not null OR C.RowNumber = 1 ) S on S.AssetUid = T.AssetUid and S.MetricAssetUid = T.MetricAssetUid and S.EffectiveDate = T.EffectiveDate and S.UpdatedOn = T.UpdatedOn where S.AssetUid is null;
update metrics.StagingScoreItem set Processing = 1 where Archived = 0;
drop table if exists #assetEffectiveDates; create table #assetEffectiveDates (AssetTypeUid uniqueidentifier not null, AssetUid uniqueidentifier not null, EffectiveDate date not null); CREATE NONCLUSTERED INDEX IX_TempAssetEffectiveDates_AssetTypeUid ON #assetEffectiveDates ([AssetTypeUid]);
insert into #assetEffectiveDates select distinct T.[Uid] as AssetTypeUid, A.[Uid] as AssetUid, R.EffectiveDate from metrics.StagingScoreItem R inner join dbo.Asset A on A.[uid] = R.AssetUid inner join dbo.AssetType T on T.ID = A.AssetTypeID where R.Archived = 0 and R.Processing = 1;
drop table if exists #step1; create table #step1 ( AssetUid uniqueidentifier not null, EffectiveDate date not null, MetricAssetUid uniqueidentifier not null, ParentUid uniqueidentifier null, IsGroup bit not null, Weight decimal(5,3) not null, [Value] bit not null ); CREATE NONCLUSTERED INDEX IX_TempStep1_Asset_Metric_EffectiveDate ON #step1 (AssetUid, MetricAssetUid, EffectiveDate); CREATE NONCLUSTERED INDEX IX_TempStep1_Asset_ParentMetric_EffectiveDate ON #step1 (AssetUid, ParentUid, EffectiveDate);
insert into #step1 select E.AssetUid, E.EffectiveDate, A.[Uid], A.ParentUid, A.IsGroup, V.Weight, coalesce(S.Result, P.Value, 0) as Value from metrics.AssetVersion V inner join metrics.Asset A on A.[Uid] = V.[Uid] inner join #assetEffectiveDates E on E.AssetTypeUid = A.AssetTypeUid and A.State = 1 cross apply ( select max(EffectiveDate) as EffectiveDate from metrics.AssetVersion where [Uid] = A.[Uid] and EffectiveDate <= E.EffectiveDate ) MV left join metrics.StagingScoreItem S on S.AssetUid = E.AssetUid and S.MetricAssetUid = V.Uid and S.EffectiveDate = E.EffectiveDate outer apply ( select top 1 AssetUid, MetricAssetUid, Value, max(EffectiveDate) OVER(PARTITION BY AssetUid, MetricAssetUid, EffectiveDate) as EffectiveDate from metrics.ScoreItem where AssetUid = E.AssetUid and MetricAssetUid = V.Uid and EffectiveDate <= S.EffectiveDate ) P where V.EffectiveDate = MV.EffectiveDate and metrics.AssetMeetsConditions(V.[Uid], V.EffectiveDate, E.AssetUid) = 1;
drop table if exists #step2; create table #step2 ( AssetUid uniqueidentifier not null, EffectiveDate date not null, MetricAssetUid uniqueidentifier not null, ParentUid uniqueidentifier null, IsGroup bit not null, IsRelevant bit, Weight decimal(5,3) not null, [Value] bit not null, [Level] int null, AdjustedWeight decimal(5,3) null, Score decimal(5,3) null ); CREATE NONCLUSTERED INDEX IX_TempStep2_Metric_IsGroup_Level ON #step2 (MetricAssetUid, IsGroup, [Level]); CREATE NONCLUSTERED INDEX IX_TempStep2_Parent_Level_IsRelevant ON #step2 (ParentUid, [Level], IsRelevant);
with h as ( select AssetUid, EffectiveDate, MetricAssetUid, ParentUid, IsGroup, Weight, Value, 1 as [Level] from #step1 where ParentUid is null union all select c.AssetUid, c.EffectiveDate, c.MetricAssetUid, c.ParentUid, c.IsGroup, c.Weight, c.Value, h.[Level] + 1 as [Level] from #step1 c inner join h on h.AssetUid = c.AssetUid and h.MetricAssetUid = c.[ParentUid] and c.EffectiveDate = h.EffectiveDate )
insert into #step2 (AssetUid, EffectiveDate, MetricAssetUid, ParentUid, IsGroup, Weight, [Value], [Level]) select * from h order by EffectiveDate, [Level];
update #step2 set IsRelevant = 1 where IsGroup = 0;
declare @maxLevel int select @maxLevel = max(Level) from #step2 while @maxLevel >= 1 begin update T set T.IsRelevant = case when [RelevantItemCount] > 0 then 1 else 0 end from #step2 T cross apply ( select count(1) as [RelevantItemCount] from #step2 where ParentUid = T.MetricAssetUid and AssetUid = T.AssetUid and EffectiveDate = T.EffectiveDate and [Level] = @maxLevel + 1 and IsRelevant = 1 ) S where T.IsGroup = 1 and T.[Level] = @maxLevel
set @maxLevel = @maxLevel - 1 end;
update T set T.AdjustedWeight = IIF(T.Weight = 0, 1, T.Weight) / IIF(S.Weight = 0, 1, S.Weight) from #step2 T outer apply ( select sum(Weight) Weight from #step2 where AssetUid = T.AssetUid and EffectiveDate = T.EffectiveDate and ( (ParentUid = T.ParentUid) or (ParentUid is null and T.ParentUid is null) ) and IsRelevant = 1 ) S;
update #step2 set Score = case [Value] when 1 then AdjustedWeight else 0 end where IsGroup = 0;
update #step2 set Score = null where IsGroup = 1;
declare @stopLevel int = 1, @currentLevel int select @currentLevel = max([Level]) from #step2;
while @currentLevel >= @stopLevel begin update T set T.Score = S.Score*AdjustedWeight from #step2 T cross apply ( select sum(coalesce(Score, AdjustedWeight)) as Score from #step2 where ParentUid = T.MetricAssetUid and EffectiveDate = T.EffectiveDate and AssetUid = T.AssetUid and [Level] = @currentLevel+1 ) S where T.[Level] = @currentLevel and T.IsGroup = 1
set @currentLevel = @currentLevel - 1 end;
update #step2 set Score = case when Value = 1 then AdjustedWeight else 0 end where Score is null;
merge metrics.Score as T using ( select AssetUid, EffectiveDate, round(sum(Score), 2) as Value from #step2 where [Level] = 1 and Score is not null and IsRelevant = 1 group by AssetUid, EffectiveDate ) S on (T.AssetUid = S.AssetUid and T.EffectiveDate = S.EffectiveDate) when matched then update set T.Value = S.Value when not matched by target then insert (AssetUid, EffectiveDate, Value) values (S.AssetUid, S.EffectiveDate, S.Value);
merge metrics.ScoreItem as T using ( select distinct AssetUid, MetricAssetUid, EffectiveDate, Value, AdjustedWeight from #step2 where IsGroup = 0 ) S on (T.AssetUid = S.AssetUid and T.MetricAssetUid = S.MetricAssetUid and T.EffectiveDate = S.EffectiveDate) when matched then update set T.AdjustedWeight = S.AdjustedWeight, T.Value = S.Value, T.UpdatedOn = getutcdate() when not matched by target then insert (AssetUid, MetricAssetUid, EffectiveDate, UpdatedOn, Value, AdjustedWeight) values (S.AssetUid, S.MetricAssetUid, S.EffectiveDate, getutcdate(), S.Value, S.AdjustedWeight);
delete T from metrics.StagingScoreItem T inner join metrics.StagingScoreItem S on S.AssetUid = T.AssetUid and S.MetricAssetUid = T.MetricAssetUid and S.EffectiveDate = T.EffectiveDate and T.Archived = 1 and S.Archived = 0 and S.Processing = 1
update metrics.StagingScoreItem set Processing = 0, Archived = 1 where Processing = 1;
commit transaction @TranName; end try begin catch rollback transaction @TranName; throw end catch end

changeSet.rollback:
