insert into #assetEffectiveDates select distinct T.[Uid] as AssetTypeUid, A.[Uid] as AssetUid, R.EffectiveDate from metrics.StagingScoreItem R inner join dbo.Asset A on A.[uid] = R.AssetUid inner join dbo.AssetType T on T.ID = A.AssetTypeID where R.Archived = 0 and R.Processing = 1;
